'use client';

import { useActionState } from 'react';

export default function ContactForm() {
  async function submitContactMessage(prevState: { message: string }, formData: FormData) {
    'use server';

    const name = formData.get('name') as string | null;
    const email = formData.get('email') as string | null;
    const message = formData.get('message') as string | null;

    if (!name || name.trim() === '') {
      return { message: 'Error: Name is required' };
    }

    if (!email || email.trim() === '') {
      return { message: 'Error: Email is required' };
    }

    if (!message || message.trim() === '') {
      return { message: 'Error: Message is required' };
    }

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) {
      return { message: 'Error: Please enter a valid email address' };
    }

    console.log('Contact message received:', { name, email, message });

    return { message: 'Success: Message sent successfully!' };
  }

  const [state, formAction] = useActionState(submitContactMessage, { message: '' });

  return (
    <div>
      <h2>Contact Us</h2>
      <form action={formAction}>
        <div>
          <label htmlFor="name">Name:</label>
          <input type="text" id="name" name="name" required />
        </div>
        <div>
          <label htmlFor="email">Email:</label>
          <input type="email" id="email" name="email" required />
        </div>
        <div>
          <label htmlFor="message">Message:</label>
          <textarea id="message" name="message" rows={5} required />
        </div>
        <button type="submit">Send Message</button>
        {state.message && (
          <p style={{ color: state.message.startsWith('Error') ? 'red' : 'green' }}>
            {state.message}
          </p>
        )}
      </form>
    </div>
  );
}
